60	    @Override
61	    public final void commit(final RocksDBStore.DBAccessor accessor,
62	                             final Position position,
63	                             final Map<TopicPartition, Long> changelogOffsets) throws RocksDBException {
64	        if (changelogOffsets.isEmpty()) {
65	            // No changelog: wipe any stale changelog-offset keys left from a prior
66	            // logging configuration, then write the current position below.
67	            wipeOffsets(accessor);
68	        } else {
