72	                final byte[] key = stringSerializer.serialize(null, tp.toString());
73	                if (offset != null) {
74	                    final byte[] value = longSerde.serializer().serialize(null, offset);
75	                    accessor.put(offsetColumnFamilyHandle, key, value);
76	                } else {
