128	    public final Long getCommittedOffset(final RocksDBStore.DBAccessor accessor, final TopicPartition partition) throws RocksDBException {
129	        final byte[] valueBytes = accessor.get(offsetColumnFamilyHandle, stringSerializer.serialize(null, partition.toString()));
130	        if (valueBytes != null) {
131	            return longSerde.deserializer().deserialize(null, valueBytes);
132	        }
133	        return null;
134	    }
135	
136	
137	    @Override
138	    public final ColumnFamilyHandle offsetsColumnFamily() {
139	        return offsetColumnFamilyHandle;
140	    }
